{
  "index": 23,
  "dataset_identifier": "ess-dive-a99be52b7a6114c-20230504T210134503379",
  "doi": "doi:10.15485/1842908",
  "archive_repository": "ESS-DIVE",
  "inclusion_decision": "include",
  "exclusion_reason": null,
  "data_payload_files": [
    "WM_SWC.csv"
  ],
  "location_metadata_files": null,
  "sensor_metadata_files": [
    "sensor_metadata.csv"
  ],
  "harmonization_mappings": {
    "datetime": {
      "pattern_1": {
        "source_pattern": "Date Time",
        "source_files": [
          "WM_SWC.csv"
        ],
        "destination_variable": "datetime_UTC",
        "transformation": "Parse local timestamp and convert to ISO 8601 UTC format. Local time treated as Mountain Standard Time (fixed UTC-7, Etc/GMT+7); the logger record is not daylight-saving adjusted.",
        "unit_conversion": null
      }
    },
    "site_id": {
      "pattern_1": {
        "source_pattern": "Point.Location",
        "source_files": [
          "WM_SWC.csv"
        ],
        "destination_variable": "site_id",
        "transformation": "Use the sensor Point.Location (upper/lower zone within each warming plot) as site_id; it is the finest-grained spatial identifier and matches the sensor metadata keys.",
        "unit_conversion": null
      }
    },
    "depth": {
      "pattern_1": {
        "source_pattern": "Depth.cm",
        "source_files": [
          "WM_SWC.csv",
          "sensor_metadata.csv"
        ],
        "destination_variable": "depth_m",
        "transformation": "Look up 'Depth.cm' for each payload 'Sensor.SN' among the SWC rows of sensor_metadata.csv. One SWC serial number lacks a recorded depth, leaving 36 payload rows with NA depth.",
        "unit_conversion": "Divide by 100 to convert from cm to m."
      }
    },
    "replicate": {
      "pattern_1": {
        "source_pattern": "Sensor.SN",
        "source_files": [
          "WM_SWC.csv"
        ],
        "destination_variable": "replicate",
        "transformation": "Number co-located sensors sequentially within each (datetime_UTC, site_id, depth_m) group; multiple SWC sensors are deployed at the same point and depth.",
        "unit_conversion": null
      }
    },
    "volumetric_water_content": {
      "pattern_1": {
        "source_pattern": "Measurement",
        "source_files": [
          "WM_SWC.csv"
        ],
        "destination_variable": "volumetric_water_content_m3_m3",
        "transformation": "Filter payload to rows where Sensor.Type == 'SWC' and rename the 'Measurement' value. WARMING MANIPULATION EXPERIMENT: plots alternate control/heated (see plot_metadata.csv); both treatments are retained and the manipulation is flagged, not excluded. Heated-plot records (ER-WM2/4/6/8/10) are confounded with the warming treatment and can be filtered downstream if an ambient-only signal is required.",
        "unit_conversion": "None; source units are already m3/m3 (volumetric fraction)."
      }
    },
    "gravimetric_water_content": {
      "pattern_1": {
        "source_pattern": null,
        "source_files": null,
        "destination_variable": "gravimetric_water_content_gH2O_gs",
        "transformation": "None; gravimetric water content not reported in source. Populate with NA.",
        "unit_conversion": null
      }
    },
    "soil_water_potential": {
      "pattern_1": {
        "source_pattern": null,
        "source_files": null,
        "destination_variable": "water_potential_kPa",
        "transformation": "None; soil water potential not reported in source. Populate with NA.",
        "unit_conversion": null
      }
    },
    "latitude": {
      "pattern_1": {
        "source_pattern": null,
        "source_files": null,
        "destination_variable": "latitude",
        "transformation": "Per-site coordinates not resolvable. Payload and ancillary files carry no coordinates; package metadata provides only a watershed-level bounding box; the referenced Varadharajan et al. (2020) location registry is not supplied in this workspace. Populate with NA and set qc_flag 'g2'.",
        "unit_conversion": null
      }
    },
    "longitude": {
      "pattern_1": {
        "source_pattern": null,
        "source_files": null,
        "destination_variable": "longitude",
        "transformation": "Per-site coordinates not resolvable (see latitude). Populate with NA and set qc_flag 'g2'.",
        "unit_conversion": null
      }
    }
  }
}
